def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    max_prev_bid = 0.0
    aggressive_count = 0
    weak_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                weak_count += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                if bid is not None:
                    prev_bids.append(float(bid))
                    if float(bid) > max_prev_bid:
                        max_prev_bid = float(bid)
                    if float(bid) >= 85:
                        aggressive_count += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return min(budget, 20.0)

    scarcity = 1.0
    if supply <= 17:
        scarcity = 1.2
    elif supply >= 23:
        scarcity = 0.9

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if day >= 8:
        danger += 1

    if prev_bids:
        target = max_prev_bid + 2.0
    else:
        target = 48.0

    if aggressive_count >= 2:
        target += 6.0
    elif aggressive_count == 1:
        target += 2.0

    target *= scarcity

    if danger >= 5:
        bid = max(95.0, target + 8.0)
    elif danger >= 3:
        bid = max(72.0, target)
    elif danger >= 2:
        bid = max(56.0, target - 6.0)
    else:
        if max_prev_bid >= 95 and hp >= 7:
            bid = 18.0
        elif max_prev_bid >= 80 and hp >= 6:
            bid = 28.0
        else:
            bid = max(34.0, target - 16.0)

    if weak_count >= 2 and danger <= 2:
        bid -= 6.0

    reserve_days = 10 - day
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(soft_cap, budget - max(0.0, reserve_days - 1) * 18.0)
        soft_cap = max(soft_cap, 0.0)

    if danger <= 1:
        bid = min(bid, max(40.0, budget * 0.18))
    elif danger == 2:
        bid = min(bid, max(65.0, budget * 0.32))
    elif danger == 3:
        bid = min(bid, max(85.0, budget * 0.48))
    else:
        bid = min(bid, max(110.0, budget * 0.72))

    if soft_cap > 0:
        bid = min(bid, soft_cap)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(budget, max_prev_bid + 5.0 if max_prev_bid > 0 else 100.0))

    bid = max(0.0, min(float(budget), float(bid)))
    return bid
